function processOrder(order, user, config) {
  // 3 clear parameters
  // Simple logic
  // Reader holds 5 concepts
  const userIsValid = isValidUser(user);
  const orderIsReady = isOrderReady(order, config);

  if (userIsValid && orderIsReady) {
