good_example.code:
class Money {
  constructor(amount, currency) {
    if (amount < 0) throw Error('amount must be >= 0');
    if (!currency) throw Error('currency required');
    this.amount = amount;
    this.currency = currency;
  }

  add(other) {
    // Object guarantees this invariant
    return new Money(this.amount + other.amount, this.currency);
  }
}

const m = new Money(-5); // Error thrown. Object can't be broken.

